def ico(n):return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="{icons[n]}"/></svg>'
def img(id,cls='',kind='monsters'):return f'<img class="pixel {cls}" src="/sprites/{kind}/{id}.png" alt="">'
def button(body,label='',cls='',attrs=''):return f'<button class="{cls}"'+(f' aria-label="{label}"' if label else '')+f' {attrs}>{body}</button>'
def badge(t):return f'<img class="type" src="/sprites/ui/type_{t}.png" alt="{t.capitalize()}">'
def hp(v,maxv,preview=None):return f'<span class="hp" role="meter" aria-label="Punti vita" aria-valuenow="{v}" aria-valuemin="0" aria-valuemax="{maxv}"><i style="width:{v/maxv*100}%"></i>'+ (f'<i class="gain" style="left:{v/maxv*100}%;width:{(preview-v)/maxv*100}%"></i>' if preview else '')+'</span>'
def header(title):return '<header class="heading"><h1>'+title+'</h1>'+button(ico('close'),'Chiudi','close','data-close')+'</header>'
mons=[('berlusconix','BERLUSCONIX',26,64,102,'media','destra'),('movimenton','MOVIMENTON',26,103,103,'istituzione',''),('mediocrate','MEDIOCRATE',17,65,65,'media',''),('giorgiagon','GIORGIAGON',24,72,88,'destra',''),('draghimon','DRAGHIMON',23,20,94,'tecno','istituzione'),('ellyna','ELLYNA',22,0,81,'sinistra','')]
def member(m,i,mini=False):
 id,name,lv,v,mx,t,t2=m
 if mini:return button(img(id)+hp(v,mx,min(mx,v+round(mx*.3)) if v and v<mx else None)+(f'<span class="gain-label">+{min(mx-v,round(mx*.3))}</span>' if v and v<mx else ''),name+' · '+str(v)+' punti vita','recipient'+(' unavailable' if not v or v==mx else ''),'data-recipient')
 return button(('<span class="leader">'+ico('star')+'</span>' if i==0 else '')+img(id,'member-sprite')+f'<span class="member-name display">{name}</span><span class="level">Lv{lv}</span><span class="member-hp">{hp(v,mx)}<span>{v}/{mx}</span></span><span class="types">'+badge(t)+(badge(t2) if t2 else '')+'</span>'+('<span class="stamp ko">KO</span>' if v==0 else ''),f'{name}, livello {lv}, {v} punti vita su {mx}'+(', capofila' if i==0 else ''),'member'+(' selected' if i==0 else '')+' '+('fainted' if not v else ''),'data-link="compagno.html"')
def move(name,pp,t='media',eff='',extra=''):
 return button(f'<strong class="display">{"APPELLO" if name == "APPELLO AGLI ALLEATI" else name}</strong><span class="move-meta">{badge(t)}<span>{pp}</span><span class="eff">{eff}</span></span>',name+' · '+pp+' PP','move '+t+(' exhausted' if pp.startswith('0/') else ''),f'data-move="{name}" '+extra)
def world():
 trees=''.join(img('tree','tree', 'tiles').replace('class="pixel tree"',f'class="pixel tree" style="left:{x}px;top:{y}px"') for x,y in [(x,y) for y in [0,96,192,960,1056] for x in range(0,960,96)]+[(x,y) for x in [0,96,768,864] for y in range(288,960,96)])
 return '<div class="world" data-world><div class="world-art"><div class="road vertical"></div><div class="road crossing"></div><div class="pond"></div><div class="tallgrass"></div>'+trees+img('build_house_front_red','house','tiles')+img('obj_bench','bench','tiles')+img('obj_flowers','flowers','tiles')+'</div>'+img('player_south','player','chars')+img('npc_journalist_west','npc','chars')+'</div>'
def world_ui(active=True):return '<div class="world-top"><span class="location tag">PERCORSO 1</span><nav class="quick">'+''.join(button(ico(ic),label,'icon-button',f'data-link="{dest}.html"') for ic,label,dest in [('team','Squadra','squadra'),('map','Mappa','mappa'),('menu','Menù','menu')])+'</nav></div>'+button('<span>›</span> Sfida lo Studio 5','Ripiega obiettivo','objective','data-collapse')+'<div class="stick" aria-hidden="true"><i></i></div><div class="world-actions">'+(button('<b>A</b><span>Parla</span>','Parla','talk','data-link="dialogo.html"') if active else '')+button(ico('run'),'Attiva corsa','run icon-button','data-run')+'</div>'
