scenes['squadra']=header('SQUADRA')+'<div class="team-list">'+''.join(member(m,i) for i,m in enumerate(mons))+'</div>'
profile='<section class="profile-hero">'+img('berlusconix','profile-sprite')+'<div><h1>BERLUSCONIX</h1><span>Lv26</span><span class="types">'+badge('media')+badge('destra')+'</span>'+hp(64,102)+'<span>64/102</span></div><span class="stamp">ELETTO</span></section>'
profile_tabs='<nav class="tabs">'+''.join(button(t,cls='active' if i==0 else '',attrs=f'data-tab="{id}"') for i,(t,id) in enumerate([('Mosse','moves'),('Valori','values'),('Storia','story')]))+'</nav>'
scenes['compagno']='<div class="profile-close">'+button(ico('close'),'Chiudi','close','data-close')+'</div>'+profile+profile_tabs+'<div class="tab-page move-list" id="moves">'+''.join([move('TELEPROMESSA','14/15'),move('APPELLO AGLI ALLEATI','15/15',eff='▲'),move('EDITORIALE','9/10',eff='▲'),move('BUNGA PARTY','0/5')])+'</div><div class="tab-page stats" id="values" hidden>'+''.join(f'<div><span>{n}</span><span class="stat-bar"><i style="width:{v}%"></i></span><b>{v}</b></div>' for n,v in [('Retorica',68),('Faccia tosta',92),('Carisma',85),('Opportunismo',74)])+'</div><div class="tab-page story" id="story" hidden><h2>Il palinsesto è suo.</h2><p>Promette una replica di tutto, tranne delle domande scomode.</p><h2>Teflon</h2><p>Gli scandali non lasciano il segno.</p><div class="evolution">'+img('telecrate')+ico('arrow')+img('berlusconix')+'</div></div>'
