scenes['borsa']=header('BORSA')+'<nav class="tabs bag-tabs">'+''.join(button(ico(ic)+f'<span>{n}</span>',cls='active' if i==0 else '',attrs='data-bag-tab') for i,(ic,n) in enumerate([('heal','Cure'),('ballot','Schede'),('tool','Strumenti'),('key','Chiave')]))+'</nav><div class="item-grid">'+''.join(button(img(id,kind='items')+f'<strong>{name}</strong><span>×{count}</span>',name+' · quantità '+str(count),'item','data-item="'+name+'"') for id,name,count in items)+'</div><div class="sheet-shade" id="item-sheet" hidden><section class="bottom-sheet"><header><h2>Caffè del bar sport</h2>'+button(ico('close'),'Chiudi oggetto','close','data-dismiss')+'</header><p>Recupera il 30% dei PV.</p><div class="recipient-row">'+''.join(member(m,i,True) for i,m in enumerate(mons))+'</div></section></div>'
