scenes['mappa']=header('ITALIETTA')+'<nav class="tabs map-tabs">'+''.join(button(n,cls='active' if i==0 else '',attrs='data-map-tab') for i,n in enumerate(['Italietta','Rotte','Atto 3']))+'</nav><div class="map-art"><div class="map-world">'+map_svg+'<div class="map-label borgo">Borgo Urne</div><div class="map-label medio">Mediopoli</div>'+button(ico('flag')+'<span>Studio 5</span>','Studio 5 · prossima tappa','map-pin','data-place')+button('<span class="here-dot"></span>','La tua posizione: Percorso 1','map-here','data-place')+'</div>'+button(ico('zoom'),'Cambia zoom mappa','map-zoom','data-zoom')+'</div><div class="sheet-shade" id="place-sheet" hidden><section class="bottom-sheet"><header><h2>Studio 5</h2>'+button(ico('close'),'Chiudi luogo','close','data-dismiss')+'</header><p>Il dibattito comincia dopo la pubblicità.</p>'+button('Viaggia · 80 €','Viaggia allo Studio 5 per 80 euro','primary','data-dismiss')+'</section></div>'
scenes['impara']=header('NUOVA MOSSA')+'<div class="learn-hero">'+img('movimenton')+'<strong class="display">MOVIMENTON</strong><span>Lv26</span></div><div class="new-move"><span class="stamp">NUOVA</span>'+move('VOTO DI FIDUCIA','20/20','istituzione')+'</div><div class="learn-list">'+''.join([move('COMIZIO','20/25','populismo'),move('SLOGAN','15/15','populismo'),move('GIRAVOLTA','12/15','centro'),move('QUORUM','10/10','istituzione')])+'</div>'+button('Non imparare',cls='decline',attrs='data-close')
scenes['menu']=world()+'<div class="veil"></div><section class="pause-sheet"><header><h1>IN PAUSA</h1>'+button(ico('close'),'Chiudi menù','close','data-close')+'</header><div class="campaign-strip"><span>'+ico('coin')+' 9.320 €</span><span>'+ico('poll')+' 100%</span></div><nav class="menu-grid">'+''.join(button(ico(ic)+f'<strong>{n}</strong>',n,'menu-entry',f'data-link="{dest}.html"') for ic,n,dest in [('team','Squadra','squadra'),('bag','Borsa','borsa'),('missions','Missioni','esplorazione'),('map','Mappa','mappa'),('dex','Politicdex','compagno'),('more','Altro','esplorazione')])+'</nav><div class="paper-edge"></div></section>'
