 (P/(id+'.html')).write_text('<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Tribuna elettorale · '+id+'</title><link rel="stylesheet" href="mock.css"></head><body class="'+id+'"><main class="screen" data-screen="'+id+'">'+content+'</main><dialog id="detail"><header><h2>Dettaglio mossa</h2>'+button(ico('close'),'Chiudi dettaglio','close','data-dismiss')+'</header><p>Potenza 70 · Precisione 100%</p><p>Colpisce prima. Danno stimato: 81–92 PV.</p></dialog><script src="mock.js"></script></body></html>')
